      { title: "Chat", folder: "chat", labels: "new", desc: "Chat with everyone.", tags: "utility" },
    ];

    let currentFilter = "home";
    let currentGame = null;

    const overlay = document.getElementById("playerOverlay");
    const gameFrame = document.getElementById("gameFrame");
    const gameTitleEl = document.getElementById("gameTitle");
    const loadingOverlay = document.getElementById("loadingOverlay");
    const topBar = document.getElementById("topBar");
    const btnFullscreen = document.getElementById("btnFullscreen");
    const btnExit = document.getElementById("btnExit");
    const cardsRow = document.getElementById("cardsRow");
    const suggestionsPanel = document.getElementById("suggestionsPanel");
    const linksPanel = document.getElementById("linksPanel");
    const placeholderPanel = document.getElementById("placeholderPanel");
    const placeholderFrame = document.getElementById("placeholderFrame");
    const homePanel = document.getElementById("homePanel");
    const cheeseCreditEl = document.getElementById("cheeseCredit");
    const searchBoxEl = document.getElementById("searchBox");

    // ── Cross-origin theme sync for R2-hosted pages/games ─────────────
    function getCurrentThemePayload() {
      const css = getComputedStyle(document.documentElement);
      const hex = (css.getPropertyValue('--accent-main') || '#8b5cf6').trim();
      const soft = (css.getPropertyValue('--accent-soft') || hex).trim();
      const warm = (css.getPropertyValue('--accent-warm') || soft).trim();
      return {
        type: 'fe-theme',
        hex,
        accentMain: hex,
        accentSoft: soft,
        accentWarm: warm,
        lightMode: document.documentElement.classList.contains('light-mode')
      };
    }

    function sendThemeToFrame(frame) {
      if (!frame || !frame.contentWindow) return;
      const theme = getCurrentThemePayload();
      // Backward-compatible message used by the learning proxy.
      frame.contentWindow.postMessage({ type: 'fe-accent', hex: theme.hex }, '*');
      // Richer message future pages/games can listen for.
      frame.contentWindow.postMessage(theme, '*');
    }

    function broadcastThemeToEmbeddedContent() {
      sendThemeToFrame(placeholderFrame);
      sendThemeToFrame(gameFrame);
    }

    // Re-send after each iframe navigation finishes loading.
    if (placeholderFrame) placeholderFrame.addEventListener('load', () => sendThemeToFrame(placeholderFrame));
    if (gameFrame) gameFrame.addEventListener('load', () => sendThemeToFrame(gameFrame));

    // Child pages can request the current theme at any time.
    window.addEventListener('message', (event) => {
      if (!event.data || event.data.type !== 'fe-theme-request') return;
      const theme = getCurrentThemePayload();
      try {
        event.source.postMessage({ type: 'fe-accent', hex: theme.hex }, '*');
        event.source.postMessage(theme, '*');
      } catch (_) {}
    });

    function filterToSlug(name) {
      if (name === "home") return "";
      if (name === "popular") return "popular";
      if (name === "new") return "new";
      if (name === "all") return "all";
      if (name === "suggestions") return "suggestions";
      if (name === "links") return "links";
      if (name === "placeholder") return "placeholder";
      return "";
    }

    function slugToFilter(slug) {
      if (!slug || slug === "home") return "home";
      if (slug === "popular") return "popular";
      if (slug === "new") return "new";
      if (slug === "all") return "all";
      if (slug === "suggestions") return "suggestions";
      if (slug === "links") return "links";
      if (slug === "placeholder") return "placeholder";
      return null;
    }

    function getCurrentPathName() {
      return decodeURIComponent(window.location.hash.replace(/^#\/?/, ""));
    }

    function getThumbSrc(folder) {
      return r2Url("games/" + folder + "/thumb.png");
    }

    function updateDocumentTitle() {
      if (currentGame) return;
      // Don't override if tab disguise is active
      if (typeof _tabDisguiseActive !== 'undefined' && _tabDisguiseActive) return;

      if (currentFilter === "home") {
        document.title = "Free Education • Home";
      } else if (currentFilter === "popular") {
        document.title = "Free Education • Popular";
      } else if (currentFilter === "new") {
        document.title = "Free Education • New Games";
      } else if (currentFilter === "all") {
        document.title = "Free Education • All Games";
      } else if (currentFilter === "suggestions") {
        document.title = "Free Education • Suggestions";
      } else if (currentFilter === "links") {
        document.title = "Free Education • Links";
      } else if (currentFilter === "placeholder") {
        document.title = "Free Education • Placeholder";
      } else {
        document.title = "Free Education • Play Free Web Games";
      }
    }

    function createCards() {
      if (currentFilter === "suggestions" || currentFilter === "home") return;

      const container = cardsRow;
      container.innerHTML = "";

      const search = (document.getElementById("searchInput").value || "").toLowerCase();
      const sorted = [...games].sort((a, b) => a.title.localeCompare(b.title));

      sorted.forEach((g) => {
        const text = (g.title + " " + (g.tags || "")).toLowerCase();
        if (search && !text.includes(search)) return;

        if (currentFilter === "popular" && !String(g.labels).includes("popular")) return;
        if (currentFilter === "new" && !String(g.labels).includes("new")) return;

        const isNew = String(g.labels).includes("new");
        const isPopular = String(g.labels).includes("popular");

        const card = document.createElement("div");
        card.className = "game-card";
        card.dataset.title = g.title;
        card.dataset.tags = g.tags || "";
        card.dataset.labels = g.labels || "";

        let badgeHTML = "";
        if (isNew) badgeHTML += `<div class="badge-pill badge-new">🆕 NEW</div>`;
        if (isPopular) badgeHTML += `<div class="badge-pill">🔥 Popular</div>`;

        const thumbSrc = getThumbSrc(g.folder);
        const hideImgs = typeof _settings !== 'undefined' && _settings.hideImages;
        const imgTag = hideImgs ? '' : `<img src="${thumbSrc}" alt="" loading="lazy"
          onload="this.parentElement.classList.remove('no-img')"
          onerror="this.remove()">`;

        card.innerHTML = `
  <div class="badge-row">
    ${badgeHTML}
  </div>
  <div class="game-thumb no-img">
    ${imgTag}
    <div class="play-circle">
      <div class="play-icon"></div>
    </div>
  </div>
  <div class="card-bottom">
    <div class="game-title">${g.title}</div>
    <div class="game-desc">${g.desc || "Play this game."}</div>
    <div class="play-link">
      Play Now <span class="arrow">▶</span>
    </div>
  </div>
`;

        card.addEventListener("click", () => openGame(g));
        container.appendChild(card);
      });
    }

    function updateViewForFilter() {
      document
        .querySelectorAll(".filter-pill")
        .forEach((pill) =>
          pill.classList.toggle("active", pill.dataset.filter === currentFilter)
        );

      updateDocumentTitle();

      if (currentFilter === "home") {
        homePanel.style.display = "block";
        suggestionsPanel.style.display = "none";
        linksPanel.style.display = "none";
        placeholderPanel.style.display = "none";
        cardsRow.style.display = "none";
        cardsRow.innerHTML = "";
        searchBoxEl.style.display = "none";
        return;
      }

      if (currentFilter === "suggestions") {
        homePanel.style.display = "none";
        cardsRow.style.display = "none";
        cardsRow.innerHTML = "";
        suggestionsPanel.style.display = "block";
        linksPanel.style.display = "none";
        placeholderPanel.style.display = "none";
        searchBoxEl.style.display = "none";
        return;
      }

      if (currentFilter === "links") {
        homePanel.style.display = "none";
        suggestionsPanel.style.display = "none";
        placeholderPanel.style.display = "none";
        cardsRow.style.display = "none";
        cardsRow.innerHTML = "";
        linksPanel.style.display = "block";
        searchBoxEl.style.display = "none";
        return;
      }

      if (currentFilter === "placeholder") {
        homePanel.style.display = "none";
        suggestionsPanel.style.display = "none";
        linksPanel.style.display = "none";
        cardsRow.style.display = "none";
        cardsRow.innerHTML = "";
        if (placeholderFrame.getAttribute("src") !== placeholderSrc) {
          placeholderFrame.removeAttribute("srcdoc");
          placeholderFrame.src = placeholderSrc;
        }
        placeholderPanel.style.display = "block";
        searchBoxEl.style.display = "none";
        return;
      }

      homePanel.style.display = "none";
      suggestionsPanel.style.display = "none";
      linksPanel.style.display = "none";
      placeholderPanel.style.display = "none";
      cardsRow.style.display = "grid";
      searchBoxEl.style.display = "flex";
      createCards();
    }

    function setFilter(name, fromHistory = false) {
      currentFilter = name;
      updateViewForFilter();

      if (!fromHistory) {
        const slug = filterToSlug(name);
        window.location.hash = slug ? "/" + slug : "/";
      }
    }

    // ── Placeholder embed controls ──────────────────────────────
    const placeholderSrc = "https://freeeducationwebproxy-v2.onrender.com/";
    const btnPhFull = document.getElementById("placeholderFullscreen");
    const btnPhNewTab = document.getElementById("placeholderNewTab");

    if (btnPhFull) {
      btnPhFull.addEventListener("click", () => {
        if (document.fullscreenElement) {
          document.exitFullscreen();
        } else if (placeholderPanel.requestFullscreen) {
          placeholderPanel.requestFullscreen();
        }
      });
    }

    // Keep the button label in sync with fullscreen state
    document.addEventListener("fullscreenchange", () => {
      if (!btnPhFull) return;
      btnPhFull.textContent = document.fullscreenElement
        ? "✕ Exit fullscreen"
        : "⛶ Fullscreen";
    });

    if (btnPhNewTab) {
  btnPhNewTab.addEventListener("click", () => {
    const rootStyles = getComputedStyle(document.documentElement);

    const accentMain = rootStyles
      .getPropertyValue("--accent-main")
      .trim();

    const accentSoft = rootStyles
      .getPropertyValue("--accent-soft")
      .trim();

    const accentWarm = rootStyles
      .getPropertyValue("--accent-warm")
      .trim();

    const lightMode =
      document.documentElement.classList.contains("light-mode");

    const url = new URL(placeholderSrc, window.location.href);

    url.searchParams.set("feAccent", accentMain);
    url.searchParams.set("feSoft", accentSoft);
    url.searchParams.set("feWarm", accentWarm);
    url.searchParams.set("feLight", lightMode ? "1" : "0");

    window.open(url.toString(), "_blank", "noopener");
  });
}

    function filterGames() {
      if (currentFilter === "suggestions" || currentFilter === "home") return;
      createCards();
    }

    function openGame(game, fromHistory = false) {
      currentGame = game;
      const src = r2Url("games/" + game.folder + "/index.html");

      gameTitleEl.textContent = game.title;
      if (typeof _tabDisguiseActive === 'undefined' || !_tabDisguiseActive) {
        document.title = game.title + " • Free Education";
      }

      if (game.title === "Cheese Chompers") {
        cheeseCreditEl.style.display = "block";
        cheeseCreditEl.innerHTML = `
          <a href="https://www.tiktok.com/@cheesechompers3d"
             target="_blank"
             style="color:${getComputedStyle(document.documentElement).getPropertyValue('--accent-main').trim()}; text-decoration:none;">
             https://www.tiktok.com/@cheesechompers3d
          </a> – used with permission
        `;
      } else {
        cheeseCreditEl.style.display = "none";
        cheeseCreditEl.innerHTML = "";
      }

      loadingOverlay.classList.remove("hidden");
      gameFrame.src = src;

      overlay.classList.remove("open");
      overlay.classList.add("from-left");
      void overlay.offsetWidth;
      overlay.classList.add("open");
      overlay.classList.remove("from-left");

      if (!fromHistory) {
        const gamePath = encodeURIComponent(game.folder);
        window.location.hash = "/" + gamePath;
      }
    }

    function closeGame() {
      overlay.classList.remove("open");
      gameFrame.src = "";
      currentGame = null;

      cheeseCreditEl.style.display = "none";
      cheeseCreditEl.innerHTML = "";

      loadingOverlay.classList.remove("hidden");
      updateDocumentTitle();
    }

    function handlePathChange() {
      const path = getCurrentPathName();

      if (!path) {
        if (overlay.classList.contains("open")) closeGame();
        if (currentFilter !== "home") {
          setFilter("home", true);
        } else {
          updateViewForFilter();
        }
        return;
      }

      const segments = path.split("/").filter(Boolean);
      const first = segments[0];

      const maybeFilter = slugToFilter(first);
      if (maybeFilter) {
        if (overlay.classList.contains("open")) closeGame();
        if (currentFilter !== maybeFilter) {
          setFilter(maybeFilter, true);
        } else {
          updateViewForFilter();
        }
        return;
      }

      const match = games.find(
        (g) => g.folder.toLowerCase() === first.toLowerCase()
      );

      if (match) {
        if (
          !overlay.classList.contains("open") ||
          !currentGame ||
          currentGame.folder !== match.folder
        ) {
          openGame(match, true);
        }
      } else {
        if (overlay.classList.contains("open")) closeGame();
        if (currentFilter !== "home") {
          setFilter("home", true);
        } else {
          updateViewForFilter();
        }
      }
    }

    function exitOverlay() {
      if (document.fullscreenElement) {
        document.exitFullscreen().catch(() => {});
        return;
      }

      closeGame();

      const slug = filterToSlug(currentFilter);
      window.location.hash = slug ? "/" + slug : "/";
    }

    btnExit.addEventListener("click", exitOverlay);

    function toggleFullscreen() {
      if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen()
          .then(() => {
            topBar.style.display = "none";
          })
          .catch(() => {});
      } else {
        document.exitFullscreen().catch(() => {});
      }
    }

    btnFullscreen.addEventListener("click", toggleFullscreen);

    document.addEventListener("fullscreenchange", () => {
      if (!document.fullscreenElement) {
        topBar.style.display = "flex";
      }
    });

    window.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && overlay.classList.contains("open") && !document.fullscreenElement) {
        exitOverlay();
      }
    });

    gameFrame.addEventListener("load", () => {
      setTimeout(() => {
        loadingOverlay.classList.add("hidden");
      }, 250);
    });

    window.addEventListener("hashchange", handlePathChange);

    window.addEventListener("load", () => {
      document.getElementById("year").textContent = new Date().getFullYear();
      handlePathChange();
      applyAllSettings();
    });

  function openSettings() {
    document.getElementById('settingsPanel').classList.add('open');
    document.getElementById('settingsOverlay').classList.add('open');
  }
  function closeSettings() {
    document.getElementById('settingsPanel').classList.remove('open');
    document.getElementById('settingsOverlay').classList.remove('open');
  }

  function openEarlyAccessOverlay() {
    const ov = document.getElementById('earlyAccessOverlay');
    ov.style.display = 'flex';
    document.getElementById('earlyCodeInput').value = '';
    document.getElementById('earlyCodeMsg').textContent = '';
    setTimeout(() => document.getElementById('earlyCodeInput').focus(), 50);
  }
  function closeEarlyAccessOverlay() {
    document.getElementById('earlyAccessOverlay').style.display = 'none';
  }
  function checkEarlyCode(val) {
    if (val.toLowerCase() === 'caca') {
      document.getElementById('earlyCodeMsg').style.color = '#22c55e';
      document.getElementById('earlyCodeMsg').textContent = '✓ Access granted!';
      setTimeout(() => { window.location.href = r2Url('pages/indexearly.html'); }, 600);
    } else if (val.length >= 4) {
      document.getElementById('earlyCodeMsg').style.color = '#38bdf8';
      document.getElementById('earlyCodeMsg').textContent = 'Incorrect code.';
    } else {
      document.getElementById('earlyCodeMsg').textContent = '';
    }
  }
  </script>

  <!-- Early Access overlay -->
  <div id="earlyAccessOverlay" style="display:none;position:fixed;inset:0;z-index:999;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);align-items:center;justify-content:center;">
    <div style="background:var(--bg-card);border:1px solid rgba(96,203,250,0.3);border-radius:20px;padding:36px 32px;max-width:340px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.7);">
      <div style="font-size:32px;margin-bottom:12px;">🔒</div>
      <div style="font-size:18px;font-weight:700;color:var(--text-main);margin-bottom:6px;">Early Access</div>
      <div style="font-size:13px;color:var(--text-muted);margin-bottom:24px;">Enter your early access code to unlock.</div>
      <input id="earlyCodeInput" type="password" placeholder="Enter code..." autocomplete="off"
        style="width:100%;box-sizing:border-box;padding:12px 16px;border-radius:12px;border:1.5px solid rgba(96,203,250,0.35);background:rgba(255,255,255,0.04);color:var(--text-main);font-size:15px;outline:none;margin-bottom:10px;text-align:center;letter-spacing:3px;"
        oninput="checkEarlyCode(this.value)"
        onkeydown="if(event.key==='Escape')closeEarlyAccessOverlay()">
      <div id="earlyCodeMsg" style="font-size:12px;color:#38bdf8;min-height:18px;margin-bottom:14px;"></div>
      <button onclick="closeEarlyAccessOverlay()" style="background:none;border:none;color:var(--text-muted);font-size:13px;cursor:pointer;text-decoration:underline;text-underline-offset:3px;">Cancel</button>
    </div>
  </div>

  <!-- Settings overlay backdrop -->
  <div class="settings-overlay" id="settingsOverlay" onclick="closeSettings()"></div>

  <!-- Settings panel -->
  <div class="settings-panel" id="settingsPanel">
